import std.collection.HashMap
import std.time.DateTime

class AccessGatewayFilter {
    public init() {}

    public func filter(request: HashMap<String, Any>): Bool {
        let path = request.get("path")?.as!().as<String>() ?? ""
        let method = request.get("method")?.as!().as<String>() ?? ""

        if (!is_start_with(path)) {
            return true
        }

        if (path == "/login" && method == "POST") {
            return true
        }

        match (get_jwt_user(request)) {
            case Some(user) =>
                set_current_user_info_and_log(user)
                return true
            case None => return false
        }
    }

    public func is_start_with(request_uri: String): Bool {
        return request_uri.startsWith("/api") || request_uri.startsWith("/login")
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers = request.get("headers")?.as!().as<HashMap<String, Any>>() ?? HashMap<String, Any>()
        let auth = headers.get("Authorization")?.as!().as<HashMap<String, Any>>() ?? HashMap<String, Any>()
        let user = auth.get("user")?.as!().as<HashMap<String, Any>>()
        return user
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        let name = user.get("name")?.as!().as<String>() ?? "unknown"
        let addr = user.get("address")?.as!().as<String>() ?? "0.0.0.0"
        println("${DateTime.now()} | ${addr} | ${name}")
    }
}

