class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let parts = command_string.split(" ").filter { it.size > 0 }
        var i = 0
        while (i < parts.size) {
            let part = parts[i]
            if (part.startsWith("--")) {
                if (part.contains("=")) {
                    let kv = part.drop(2).split("=", 1)
                    let key = kv[0]
                    let value = kv[1]
                    if (types.contains(key)) {
                        arguments[key] = convert_type(key, value)
                    } else {
                        arguments[key] = value
                    }
                } else {
                    let key = part.drop(2)
                    if (types.contains(key)) {
                        arguments[key] = convert_type(key, "true")
                    } else {
                        arguments[key] = true
                    }
                }
            } else if (part.startsWith("-") && part.size > 1) {
                let key = part.drop(1)
                if (i + 1 < parts.size && !parts[i + 1].startsWith("-")) {
                    let value = parts[i + 1]
                    if (types.contains(key)) {
                        arguments[key] = convert_type(key, value)
                    } else {
                        arguments[key] = value
                    }
                    i += 1
                } else {
                    if (types.contains(key)) {
                        arguments[key] = convert_type(key, "true")
                    } else {
                        arguments[key] = true
                    }
                }
            }
            i += 1
        }
        let missing = HashSet<String>()
        for (r in required) {
            if (!arguments.contains(r)) {
                missing.insert(r)
            }
        }
        if (missing.size > 0) {
            return (false, Some(missing))
        }
        return (true, None)
    }

    public func get_argument(key: String): Any {
        return arguments.get(key).orElse(None)
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        types[arg] = arg_type
        if (required) {
            this.required.insert(arg)
        }
    }

    public func convert_type(arg: String, value: String): Any {
        let t = types.get(arg).orElse(TypeInfo.of<String>())
        if (t == TypeInfo.of<Int64>()) {
            return Int64.parse(value)
        } else if (t == TypeInfo.of<Int32>()) {
            return Int32.parse(value)
        } else if (t == TypeInfo.of<Bool>()) {
            return value == "true"
        } else {
            return value
        }
    }
}

