import std.collection.HashMap
import std.collection.ArrayList
import std.option.Option

class Student <: Equatable<Student> {
    let name: String
    let grade: Int64
    let major: String
    let cources: HashMap<String, Int64>

    public init(name: String, grade: Int64, major: String) {
        this.name = name
        this.grade = grade
        this.major = major
        this.cources = HashMap<String, Int64>()
    }

    public override operator func != (that: Student): Bool {
        var flag = false
        if (this.name != that.name) {
            flag = true
        }
        if (this.grade != that.grade) {
            flag = true
        }
        if (this.major != that.major) {
            flag = true
        }
        for ((k, v) in this.cources) {
            if (!that.cources.contains(k)) {
                flag = true
            } else {
                if (v != that.cources[k]) {
                    flag = true
                }
            }
        }
        return flag
    }

    public override operator func == (that: Student): Bool {
        if (this.name != that.name) {
            return false
        }
        if (this.grade != that.grade) {
            return false
        }
        if (this.major != that.major) {
            return false
        }
        for ((k, v) in this.cources) {
            if (!that.cources.contains(k)) {
                return false
            }
            if (v != that.cources[k]) {
                return false
            }
        }
        return true
    }
}

class AssessmentSystem {
    let students: HashMap<String, Student>

    public init() {
        this.students = HashMap<String, Student>()
    }

    public func add_student(name: String, grade: Int64, major: String): Unit {
        let student = Student(name, grade, major)
        this.students[name] = student
    }

    public func add_course_score(name: String, course: String, score: Int64): Unit {
        if (this.students.contains(name)) {
            this.students[name].cources[course] = score
        }
    }

    public func get_gpa(name: String): Option<Float64> {
        if (!this.students.contains(name)) {
            return Option<Float64>.None
        }
        let courses = this.students[name].cources
        if (courses.size() == 0) {
            return Option<Float64>.None
        }
        var sum: Float64 = 0.0
        for ((k, v) in courses) {
            sum += Float64(v)
        }
        let avg = sum / Float64(courses.size())
        return Option<Float64>.Some(avg)
    }

    public func get_all_students_with_fail_course(): ArrayList<String> {
        let res = ArrayList<String>()
        for ((name, student) in this.students) {
            var hasFail = false
            for ((k, v) in student.cources) {
                if (v < 60) {
                    hasFail = true
                    break
                }
            }
            if (hasFail) {
                res.append(name)
            }
        }
        return res
    }

    public func get_course_average(course: String): Option<Float64> {
        var sum: Float64 = 0.0
        var cnt: Int64 = 0
        for ((name, student) in this.students) {
            if (student.cources.contains(course)) {
                sum += Float64(student.cources[course])
                cnt += 1
            }
        }
        if (cnt == 0) {
            return Option<Float64>.None
        }
        return Option<Float64>.Some(sum / Float64(cnt))
    }

    public func get_top_student(): Option<String> {
        var topName: Option<String> = Option<String>.None
        var maxGpa: Float64 = -1.0
        for ((name, student) in this.students) {
            let gpaOpt = this.get_gpa(name)
            match (gpaOpt) {
                case Some(gpa) =>
                    if (gpa > maxGpa) {
                        maxGpa = gpa
                        topName = Option<String>.Some(name)
                    }
                case None => ()
            }
        }
        return topName
    }
}

