import std.regex.*
import std.collection.HashMap
import std.collection.ArrayList

class AutomaticGuitarSimulator {
    let play_text: String

    public init(text: String) {
        this.play_text = text
    }

    public func interpret(display!: Bool = false): ArrayList<HashMap<String, String>> {
        let result = ArrayList<HashMap<String, String>>()
        if (play_text.trim().isEmpty()) {
            return result
        }
        let r = Regex("([A-G][m]?)\\d+")
        var pos = 0
        while (true) {
            let m = r.find(play_text[pos..], group: true)
            match (m) {
                case Some(md) =>
                    let chord = md.group(1).getOrThrow()
                    let start = md.start(0)
                    let end = md.end(0)
                    let tune = play_text[pos + start + chord.size..pos + end]
                    let map = HashMap<String, String>()
                    map["Chord"] = chord
                    map["Tune"] = tune
                    result.append(map)
                    if (display) {
                        println(display(chord, tune))
                    }
                    pos += end
                case None => break
            }
        }
        return result
    }

    public func display(key: String, value: String): String {
        return "Normal Guitar Playing -- Chord: ${key}, Play Tune: ${value}"
    }
}

