import std.collection.ArrayList

class AvgPartition {
    let lst: ArrayList<Int64>
    let limit: Int64

    public init(lst: ArrayList<Int64>, limit: Int64) {
        this.lst = lst
        this.limit = limit
    }

    public func setNum(): (Int64, Int64) {
        let len = this.lst.size
        return (len / this.limit, len % this.limit)
    }

    public func get(index: Int64): ArrayList<Int64> {
        let (q, r) = this.setNum()
        let start = index * q + (index > r ? r : index)
        let size = q + (index < r ? 1 : 0)
        return this.lst.slice(start..start + size)
    }
}

