import std.collection.ArrayList

class BoyerMooreSearch {

    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        let idx = patLen - 1
        while (idx >= 0) {
            if (pattern[idx] == char[0]) {
                return idx
            }
            idx -= 1
        }
        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        var patIdx = patLen - 1
        while (patIdx >= 0) {
            let textIdx = currentPos + patIdx
            if (textIdx >= textLen) {
                return patIdx
            }
            if (pattern[patIdx] != text[textIdx]) {
                return patIdx
            }
            patIdx -= 1
        }
        return -1
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        let occurrences = ArrayList<Int64>()
        var currentPos = 0
        while (currentPos <= textLen - patLen) {
            let badCharPos = mismatch_in_text(currentPos)
            if (badCharPos == -1) {
                occurrences.append(currentPos)
                currentPos += 1
            } else {
                let badChar = text[currentPos + badCharPos]
                let lastInPat = match_in_pattern(String(badChar))
                let shift = match (lastInPat) {
                    case -1 => badCharPos + 1
                    case _ => badCharPos - lastInPat
                }
                currentPos += shift
            }
        }
        return occurrences
    }
}

