import std.collection.HashMap
import std.collection.ArrayList
import std.convert.*

class Calculator {

    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        let operand_stack = ArrayList<Float64>()
        let operator_stack = ArrayList<String>()

        var i = 0
        while (i < expression.size) {
            let c = expression[i]
            if (c == ' ') {
                i += 1
                continue
            }

            if (c >= '0' && c <= '9') {
                var num = 0.0
                while (i < expression.size && ((expression[i] >= '0' && expression[i] <= '9') || expression[i] == '.')) {
                    if (expression[i] == '.') {
                        var frac = 1.0
                        i += 1
                        while (i < expression.size && (expression[i] >= '0' && expression[i] <= '9')) {
                            frac *= 0.1
                            num += Float64(expression[i] - '0') * frac
                            i += 1
                        }
                        break
                    } else {
                        num = num * 10.0 + Float64(expression[i] - '0')
                        i += 1
                    }
                }
                operand_stack.append(num)
                continue
            }

            if (c == '+' || c == '-' || c == '*' || c == '/' || c == '^') {
                while (operator_stack.size() > 0 &&
                       precedence(operator_stack[operator_stack.size() - 1]) >= precedence(c.toString())) {
                    let (new_ops, new_ors) = apply_operator(operand_stack, operator_stack)
                    operand_stack.clear()
                    operator_stack.clear()
                    for (item in new_ops) {
                        operand_stack.append(item)
                    }
                    for (item in new_ors) {
                        operator_stack.append(item)
                    }
                }
                operator_stack.append(c.toString())
            }
            i += 1
        }

        while (operator_stack.size() > 0) {
            let (new_ops, new_ors) = apply_operator(operand_stack, operator_stack)
            operand_stack.clear()
            operator_stack.clear()
            for (item in new_ops) {
                operand_stack.append(item)
            }
            for (item in new_ors) {
                operator_stack.append(item)
            }
        }

        if (operand_stack.size() == 1) {
            return Some(operand_stack[0])
        } else {
            return None
        }
    }

    public func precedence(op: String): Int64 {
        if (op == "^") {
            return 3
        } else if (op == "*" || op == "/") {
            return 2
        } else if (op == "+" || op == "-") {
            return 1
        } else {
            return 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        let new_ops = ArrayList<Float64>()
        let new_ors = ArrayList<String>()

        let op = operator_stack[operator_stack.size() - 1]
        operator_stack.remove(operator_stack.size() - 1)

        let b = operand_stack[operand_stack.size() - 1]
        operand_stack.remove(operand_stack.size() - 1)
        let a = operand_stack[operand_stack.size() - 1]
        operand_stack.remove(operand_stack.size() - 1)

        let f = operators.get(op).getOrElse({x: Float64, y: Float64 => 0.0})
        let res = f(a, b)

        for (item in operand_stack) {
            new_ops.append(item)
        }
        new_ops.append(res)

        for (item in 0..operator_stack.size()) {
            new_ors.append(operator_stack[item])
        }

        return (new_ops, new_ors)
    }
}

