        let den = c2.real * c2.real + c2.imaginary * c2.imaginary
        let r = (c1.real * c2.real + c1.imaginary * c2.imaginary) / den
        let i = (c1.imaginary * c2.real - c1.real * c2.imaginary) / den
        return ComplexNumber(r, i)
    }
}
