class CSVProcessor {
    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()
        let file = File(file_name, Read)
        let reader = StringReader(file)
        var first = true
        while (true) {
            let line = reader.readln()
            if (line == None) {
                break
            }
            let parts = line.get().split(",")
            if (first) {
                for (p in parts) {
                    title.append(p)
                }
                first = false
            } else {
                let row = ArrayList<String>()
                for (p in parts) {
                    row.append(p)
                }
                data.append(row)
            }
        }
        (title, data)
    }

