import std.collection.HashMap
import std.collection.ArrayList
import std.math.round
import std.math.abs
import std.sort.sort

class DataStatistics {

    public func mean(data: ArrayList<Int64>): Float64 {
        var sum: Int64 = 0
        for (x in data) {
            sum += x
        }
        return round(Float64(sum) / Float64(data.size()) * 100.0) / 100.0
    }

    public func median(data: ArrayList<Int64>): Float64 {
        if (data.size() == 0) {
            return 0.0
        }
        var sorted = ArrayList<Int64>(data)
        sort(sorted)
        let n = sorted.size()
        if (n % 2 == 1) {
            return round(Float64(sorted[n / 2]) * 100.0) / 100.0
        } else {
            let mid = (Float64(sorted[n / 2 - 1]) + Float64(sorted[n / 2])) / 2.0
            return round(mid * 100.0) / 100.0
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        var freq = HashMap<Int64, Int64>()
        for (x in data) {
            freq[x] = freq.getOrDefault(x, 0) + 1
        }
        var maxCount: Int64 = 0
        for ((_, v) in freq) {
            if (v > maxCount) {
                maxCount = v
            }
        }
        var modes = ArrayList<Int64>()
        for ((k, v) in freq) {
            if (v == maxCount) {
                modes.append(k)
            }
        }
        sort(modes)
        return modes
    }
}

