import std.math.abs

class DataStatistics2 {
    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        this.data = data
    }

    public func get_sum(): Float64 {
        var s = 0.0
        for (d in data) { s += d }
        return s
    }

    public func get_min(): Float64 {
        if (data.size() == 0) { return 0.0 }
        var m = data[0]
        for (i in 1..data.size()) {
            if (data[i] < m) { m = data[i] }
        }
        return m
    }

    public func get_max(): Float64 {
        if (data.size() == 0) { return 0.0 }
        var m = data[0]
        for (i in 1..data.size()) {
            if (data[i] > m) { m = data[i] }
        }
        return m
    }

    public func get_variance(): Float64 {
        let n = data.size()
        if (n == 0) { return 0.0 }
        let mean = get_sum() / (n.toFloat64())
        var v = 0.0
        for (d in data) {
            let t = d - mean
            v += t * t
        }
        return round(v / (n.toFloat64()) * 100.0) / 100.0
    }

    public func get_std_deviation(): Float64 {
        return round(sqrt(get_variance()) * 100.0) / 100.0
    }

    public func get_correlation(): Float64 {
        if (data.size() < 2) { return 0.0 }
        return 1.0
    }
}

