import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size()
        if (n != data2.size() || n == 0) {
            return 0.0
        }
        var sum1 = 0.0
        var sum2 = 0.0
        var sum1Sq = 0.0
        var sum2Sq = 0.0
        var pSum = 0.0
        for (i in 0..n) {
            let x = data1[i]
            let y = data2[i]
            sum1 += x
            sum2 += y
            sum1Sq += x * x
            sum2Sq += y * y
            pSum += x * y
        }
        let num = pSum - sum1 * sum2 / Float64(n)
        let den = sqrt((sum1Sq - sum1 * sum1 / Float64(n)) * (sum2Sq - sum2 * sum2 / Float64(n)))
        if (den == 0.0) {
            return 0.0
        }
        return num / den
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        if (n < 3) {
            return 0.0
        }
        var mean = 0.0
        for (x in data) {
            mean += x
        }
        mean /= Float64(n)
        var m2 = 0.0
        var m3 = 0.0
        for (x in data) {
            let d = x - mean
            m2 += d * d
            m3 += d * d * d
        }
        m2 /= Float64(n)
        m3 /= Float64(n)
        let sigma = sqrt(m2)
        if (sigma == 0.0) {
            return 0.0
        }
        return m3 / (sigma * sigma * sigma)
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        if (n < 4) {
            return 0.0
        }
        var mean = 0.0
        for (x in data) {
            mean += x
        }
        mean /= Float64(n)
        var m2 = 0.0
        var m4 = 0.0
        for (x in data) {
            let d = x - mean
            let d2 = d * d
            m2 += d2
            m4 += d2 * d2
        }
        m2 /= Float64(n)
        m4 /= Float64(n)
        let sigma2 = m2
        if (sigma2 == 0.0) {
            return 0.0
        }
        return m4 / (sigma2 * sigma2) - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let res = ArrayList<Float64>()
        if (sigma <= 0.0) {
            return res
        }
        let coef = 1.0 / (sigma * sqrt(2.0 * 3.141592653589793))
        let sigma2 = sigma * sigma
        for (x in data) {
            let diff = x - mu
            let exponent = -0.5 * diff * diff / sigma2
            res.append(coef * exp(exponent))
        }
        return res
    }
}

