import std.collection.ArrayList

class DecryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        var result = ""
        for (c in ciphertext) {
            if (c >= 'a' && c <= 'z') {
                let base = 'a'.code() - 0
                let offset = (c.code() - base - shift % 26 + 26) % 26
                result += Char.fromCode(base + offset)
            } else if (c >= 'A' && c <= 'Z') {
                let base = 'A'.code() - 0
                let offset = (c.code() - base - shift % 26 + 26) % 26
                result += Char.fromCode(base + offset)
            } else {
                result += c
            }
        }
        return result
    }

    public func vigenere_decipher(ciphertext: String): String {
        var result = ""
        let keyLen = key.size
        var keyIndex = 0
        for (c in ciphertext) {
            if (c >= 'a' && c <= 'z') {
                let keyChar = key[keyIndex % keyLen]
                let shift = (keyChar.code() - 'a'.code()) % 26
                let base = 'a'.code() - 0
                let offset = (c.code() - base - shift + 26) % 26
                result += Char.fromCode(base + offset)
                keyIndex += 1
            } else if (c >= 'A' && c <= 'Z') {
                let keyChar = key[keyIndex % keyLen]
                let shift = (keyChar.code() - 'a'.code()) % 26
                let base = 'A'.code() - 0
                let offset = (c.code() - base - shift + 26) % 26
                result += Char.fromCode(base + offset)
                keyIndex += 1
            } else {
                result += c
            }
        }
        return result
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        let n = encrypted_text.size
        var railMatrix = Array<Array<Char>>(rails, item: Array<Char>(n, item: '\0'))
        var dir = 1
        var row = 0
        for (i in 0..n) {
            railMatrix[row][i] = '*'
            if (row == 0) {
                dir = 1
            } else if (row == rails - 1) {
                dir = -1
            }
            row += dir
        }
        var index = 0
        for (i in 0..rails) {
            for (j in 0..n) {
                if (railMatrix[i][j] == '*' && index < n) {
                    railMatrix[i][j] = encrypted_text[index]
                    index += 1
                }
            }
        }
        var result = ""
        row = 0
        dir = 1
        for (i in 0..n) {
            result += railMatrix[row][i]
            if (row == 0) {
                dir = 1
            } else if (row == rails - 1) {
                dir = -1
            }
            row += dir
        }
        return result
    }
}

