import std.collection.ArrayList

class EncryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        let sb = StringBuilder()
        for (c in plaintext) {
            if (c >= 'a' && c <= 'z') {
                let offset = ((Int64(c) - Int64('a') + shift) % 26 + 26) % 26
                sb.append(Char(Int64('a') + offset))
            } else if (c >= 'A' && c <= 'Z') {
                let offset = ((Int64(c) - Int64('A') + shift) % 26 + 26) % 26
                sb.append(Char(Int64('A') + offset))
            } else {
                sb.append(c)
            }
        }
        return sb.toString()
    }

    public func vigenere_cipher(plain_text: String): String {
        let sb = StringBuilder()
        let keyLen = this.key.size
        var keyIndex = 0
        for (c in plain_text) {
            if (c >= 'a' && c <= 'z') {
                let shift = Int64(this.key[keyIndex % keyLen]) - Int64('a')
                let offset = ((Int64(c) - Int64('a') + shift) % 26 + 26) % 26
                sb.append(Char(Int64('a') + offset))
                keyIndex++
            } else if (c >= 'A' && c <= 'Z') {
                let shift = Int64(this.key[keyIndex % keyLen].toLower()) - Int64('a')
                let offset = ((Int64(c) - Int64('A') + shift) % 26 + 26) % 26
                sb.append(Char(Int64('A') + offset))
                keyIndex++
            } else {
                sb.append(c)
            }
        }
        return sb.toString()
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        if (rails <= 1) {
            return plain_text
        }
        let railArr = ArrayList<StringBuilder>()
        for (_ in 0..rails) {
            railArr.append(StringBuilder())
        }
        var rail: Int64 = 0
        var down = true
        for (c in plain_text) {
            railArr[rail].append(c)
            if (down) {
                rail++
                if (rail == rails - 1) {
                    down = false
                }
            } else {
                rail--
                if (rail == 0) {
                    down = true
                }
            }
        }
        let sb = StringBuilder()
        for (r in railArr) {
            sb.append(r.toString())
        }
        return sb.toString()
    }
}

