import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        prepare(expression)
        let stack = ArrayList<Float64>()
        for (item in postfix_stack) {
            if (!is_operator(item)) {
                stack.append(Float64.parse(item))
            } else {
                let second = stack.removeLast()
                let first = stack.removeLast()
                let res = when (item) {
                    "+" => first + second
                    "-" => first - second
                    "*" => first * second
                    "/" => first / second
                    "%" => first % second
                    _ => 0.0
                }
                stack.append(res)
            }
        }
        return stack[0]
    }

    public func prepare(expression: String): Unit {
        postfix_stack.clear()
        let ops = ArrayList<String>()
        let clean = transform(expression)
        let tokens = Regex("""\s+""").split(clean)
        for (tok in tokens) {
            if (tok == "(") {
                ops.append(tok)
            } else if (tok == ")") {
                while (ops.size() > 0 && ops[ops.size() - 1] != "(") {
                    postfix_stack.append(ops.removeLast())
                }
                if (ops.size() > 0) {
                    ops.removeLast()
                }
            } else if (is_operator(tok)) {
                while (ops.size() > 0 && compare(tok, ops[ops.size() - 1])) {
                    postfix_stack.append(ops.removeLast())
                }
                ops.append(tok)
            } else {
                postfix_stack.append(tok)
            }
        }
        while (ops.size() > 0) {
            postfix_stack.append(ops.removeLast())
        }
    }

    public static func is_operator(c: String): Bool {
        return c == "+" || c == "-" || c == "*" || c == "/" || c == "(" || c == ")" || c == "%"
    }

    public func compare(cur: String, peek: String): Bool {
        let curP = priority(cur)
        let peekP = priority(peek)
        return curP <= peekP
    }

    private func priority(op: String): Int64 {
        return when (op) {
            "+" => 1
            "-" => 1
            "*" => 2
            "/" => 2
            "%" => 2
            "(" => 0
            _ => -1
        }
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        let a = Float64.parse(first_value.toString())
        let b = Float64.parse(second_value.toString())
        let res = when (current_op) {
            "+" => a + b
            "-" => a - b
            "*" => a * b
            "/" => a / b
            "%" => a % b
            _ => 0.0
        }
        return Decimal(res.toString())
    }

    public static func transform(expression: String): String {
        return Regex("""\s+""").replaceAll(expression, "")
    }
}

