import std.collection.ArrayList
import std.collection.*

class GomokuGame {

    let board_size: Int64
    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(board_size: Int64) {
        this.board_size = board_size
        this.board = ArrayList<ArrayList<String>>()
        this.current_player = "X"
        for (_ in 0..board_size) {
            let row: ArrayList<String> = ArrayList<String>()
            for (_ in 0..board_size) {
                row.add(" ")
            }
            board.add(row)
        }
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if (row < 0 || row >= board_size || col < 0 || col >= board_size) {
            return false
        }
        if (board[row][col] != " ") {
            return false
        }
        board[row][col] = current_player
        current_player = (current_player == "X") ? "O" : "X"
        return true
    }

    public func check_winner(): Option<String> {
        for (r in 0..board_size) {
            for (c in 0..board_size) {
                let sym = board[r][c]
                if (sym == " ") { continue }
                let dirs = [(0, 1), (1, 0), (1, 1), (1, -1)]
                for ((dr, dc) in dirs) {
                    if (_check_five_in_a_row(r, c, (dr, dc))) {
                        return Option(sym)
                    }
                }
            }
        }
        return Option<String>(None)
    }

    public func _check_five_in_a_row(row: Int64, col: Int64, direction: (Int64, Int64)): Bool {
        let (dr, dc) = direction
        let sym = board[row][col]
        if (sym == " ") { return false }
        var count = 1
        // forward
        var (rr, cc) = (row + dr, col + dc)
        while (rr >= 0 && rr < board_size && cc >= 0 && cc < board_size && board[rr][cc] == sym) {
            count += 1
            (rr, cc) = (rr + dr, cc + dc)
        }
        // backward
        (rr, cc) = (row - dr, col - dc)
        while (rr >= 0 && rr < board_size && cc >= 0 && cc < board_size && board[rr][cc] == sym) {
            count += 1
            (rr, cc) = (rr - dr, cc - dc)
        }
        return count >= 5
    }
}

