import std.collection.HashMap

class Hotel {

    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        let available = available_rooms.get(room_type)
        if (available is None) {
            return "false"
        }
        let count = available.unwrap()
        if (room_number <= count) {
            available_rooms.put(room_type, count - room_number)
            let guest_map = booked_rooms.getOrDefault(room_type, HashMap<String, Int64>())
            let booked = guest_map.getOrDefault(name, 0)
            guest_map.put(name, booked + room_number)
            booked_rooms.put(room_type, guest_map)
            return "Success!"
        } else if (count > 0) {
            return "${count}"
        } else {
            return "false"
        }
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        let guest_map = booked_rooms.get(room_type)
        if (guest_map is None) {
            return false
        }
        let booked = guest_map.unwrap().get(name)
        if (booked is None || booked.unwrap() < room_number) {
            return false
        }
        let new_booked = booked.unwrap() - room_number
        if (new_booked == 0) {
            guest_map.unwrap().remove(name)
        } else {
            guest_map.unwrap().put(name, new_booked)
        }
        let current_available = available_rooms.getOrDefault(room_type, 0)
        available_rooms.put(room_type, current_available + room_number)
        return true
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        let current = available_rooms.getOrDefault(room_type, 0)
        available_rooms.put(room_type, current + room_number)
    }

    public func get_available_rooms(room_type: String): Int64 {
        available_rooms.getOrDefault(room_type, 0)
    }
}

