import std.collection.ArrayList

class Interpolation {
    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let n = x.size()
        let m = x_interp.size()
        let result = ArrayList<Float64>()
        for (i in 0..m) {
            let xi = x_interp[i]
            if (xi <= x[0]) {
                result.append(y[0])
                continue
            }
            if (xi >= x[n-1]) {
                result.append(y[n-1])
                continue
            }
            for (j in 0..(n-1)) {
                if (xi >= x[j] && xi <= x[j+1]) {
                    let t = (xi - x[j]) / (x[j+1] - x[j])
                    let yi = y[j] + t * (y[j+1] - y[j])
                    result.append(yi)
                    break
                }
            }
        }
        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let nx = x.size()
        let ny = y.size()
        let m = x_interp.size()
        let result = ArrayList<Float64>()
        for (k in 0..m) {
            let xi = x_interp[k]
            let yi = y_interp[k]
            var ix = 0
            var iy = 0
            for (i in 0..(nx-2)) {
                if (xi >= x[i] && xi <= x[i+1]) {
                    ix = i
                    break
                }
            }
            for (j in 0..(ny-2)) {
                if (yi >= y[j] && yi <= y[j+1]) {
                    iy = j
                    break
                }
            }
            let x0 = x[ix]
            let x1 = x[ix+1]
            let y0 = y[iy]
            let y1 = y[iy+1]
            let z00 = z[ix][iy]
            let z10 = z[ix+1][iy]
            let z01 = z[ix][iy+1]
            let z11 = z[ix+1][iy+1]
            let t = (xi - x0) / (x1 - x0)
            let u = (yi - y0) / (y1 - y0)
            let z0 = z00 + t * (z10 - z00)
            let z1 = z01 + t * (z11 - z01)
            let zi = z0 + u * (z1 - z0)
            result.append(zi)
        }
        return result
    }
}

