import std.convert.*
import std.collection.*

class IPAddress {
    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let parts = ip_address.split(".").filter{e => e.size > 0}
        if (parts.size != 4) {
            return false
        }
        for (p in parts) {
            match (UInt32.tryParse(p)) {
                case Some(v) =>
                    if (v > 255) {
                        return false
                    }
                case None => return false
            }
        }
        true
    }

    public func get_octets(): ArrayList<String> {
        if (!is_valid()) {
            return ArrayList<String>()
        }
        let res = ArrayList<String>()
        for (s in ip_address.split(".").filter{e => e.size > 0}) {
            res.append(s)
        }
        res
    }

    public func get_binary(): String {
        if (!is_valid()) {
            return ""
        }
        let parts = ip_address.split(".").filter{e => e.size > 0}
        let buf = StringBuilder()
        for (i in 0..4) {
            let v = UInt32.parse(parts[i])
            let bits = UInt32.toString(v, 2)
            let pad = "0".repeat(8 - bits.size) + bits
            buf.append(pad)
            if (i != 3) {
                buf.append(".")
            }
        }
        buf.toString()
    }
}

