        let job = JobListing(job_title, company, requirements)
        jobListings.add(job)
    }

    public func remove_job(job: JobListing): Unit {
        let idx = jobListings.indexOf(job)
        match (idx) {
            case Some(i) => jobListings.remove(i)
            case None => ()
        }
    }

