import std.collection.ArrayList
import std.math.*

class KappaCalculator {
    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        let total: Float64 = 0.0
        let agree: Float64 = 0.0
        for (row in testData) {
            for (v in row) {
                total += Float64(v)
            }
        }
        for (row in testData) {
            var rowSum: Float64 = 0.0
            for (v in row) {
                rowSum += Float64(v)
            }
            for (v in row) {
                agree += Float64(v) * (Float64(v) - 1.0)
            }
        }
        let pe = agree / (total * (total - 1.0))
        let pa = (total * total - total) / (total * total - total)
        return (pa - pe) / (1.0 - pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var p: Array<Float64> = Array<Float64>(k, (_) => 0.0)
        var P: Array<Float64> = Array<Float64>(N, (_) => 0.0)
        for (i in 0..N) {
            var rowSum: Float64 = 0.0
            for (j in 0..k) {
                let v = Float64(testData[i][j])
                p[j] += v
                rowSum += v
            }
            var sumSq: Float64 = 0.0
            for (j in 0..k) {
                let v = Float64(testData[i][j])
                sumSq += v * v
            }
            P[i] = (sumSq - rowSum) / (rowSum * (rowSum - 1.0))
        }
        var pBar: Float64 = 0.0
        for (pv in P) {
            pBar += pv
        }
        pBar /= Float64(N)
        var pe: Float64 = 0.0
        for (j in 0..k) {
            let pj = p[j] / Float64(N * n)
            pe += pj * pj
        }
        return (pBar - pe) / (1.0 - pe)
    }
}

