import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let rand = Random()
        var newBoard = ArrayList<ArrayList<String>>()
        for (i in 0..rows) {
            var row = ArrayList<String>()
            for (j in 0..cols) {
                let idx = rand.nextInt64(ICONS.size)
                row.append(ICONS[idx])
            }
            newBoard.append(row)
        }
        return newBoard
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        let rowMax = BOARD_SIZE[0]
        let colMax = BOARD_SIZE[1]
        if (x1 < 0 || x1 >= rowMax || y1 < 0 || y1 >= colMax ||
            x2 < 0 || x2 >= rowMax || y2 < 0 || y2 >= colMax) {
            return false
        }
        if (x1 == x2 && y1 == y2) {
            return false
        }
        if (board[x1][y1] != board[x2][y2]) {
            return false
        }
        return has_path(pos1, pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        var visited = ArrayList<(Int64, Int64)>()
        return dfs(pos1, pos2, 0, visited)
    }

    private func dfs(pos: (Int64, Int64), target: (Int64, Int64), turns: Int64, visited: ArrayList<(Int64, Int64)>): Bool {
        let (x, y) = pos
        let (tx, ty) = target
        if (x == tx && y == ty) {
            return true
        }
        if (turns > 2) {
            return false
        }
        let posNow = (x, y)
        if (contains(visited, posNow)) {
            return false
        }
        let rowMax = BOARD_SIZE[0]
        let colMax = BOARD_SIZE[1]
        if (x == -1 && y == -1) {
            for (i in 0..rowMax) {
                for (j in 0..colMax) {
                    if (i == 0 || i == rowMax - 1 || j == 0 || j == colMax - 1) {
                        let newVisited = ArrayList<(Int64, Int64)>(visited)
                        newVisited.append(posNow)
                        if (dfs((i, j), target, turns, newVisited)) {
                            return true
                        }
                    }
                }
            }
            return false
        }
        if (x < 0 || x >= rowMax || y < 0 || y >= colMax) {
            return false
        }
        if (board[x][y] != " " && !(x == tx && y == ty)) {
            return false
        }
        let newVisited = ArrayList<(Int64, Int64)>(visited)
        newVisited.append(posNow)
        let dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        for (d in dirs) {
            let (dx, dy) = d
            let nx = x + dx
            let ny = y + dy
            let newTurns = if (visited.size > 0 && visited[visited.size - 1] != (x, y)) {
                turns + 1
            } else {
                turns
            }
            if (dfs((nx, ny), target, newTurns, newVisited)) {
                return true
            }
        }
        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        board[x1][y1] = " "
        board[x2][y2] = " "
    }

    public func is_game_over(): Bool {
        for (row in board) {
            for (cell in row) {
                if (cell != " ") {
                    return false
                }
            }
        }
        return true
    }
}
