        let size = this.playlist.size()
        for (i in 0..size) {
            if (this.playlist[i] == song) {
                this.playlist.remove(i)
                if (this.current_song == Some(song)) {
                    this.stop()
                }
                return
            }
        }
    }

    public func play(): Option<String> {
        if (this.playlist.isEmpty()) {
            return None
        }
        if (this.current_index == -1) {
            this.current_index = 0
            this.current_song = Some(this.playlist[0])
        }
        this.current_song
    }

    public func stop(): Bool {
        if (this.current_song != None) {
            this.current_song = None
            this.current_index = -1
            return true
        }
        return false
    }

    public func switch_song(): Bool {
        if (this.current_index >= 0 && this.current_index < this.playlist.size() - 1) {
            this.current_index += 1
            this.current_song = Some(this.playlist[this.current_index])
            return true
        }
        return false
    }

    public func previous_song(): Bool {
        if (this.current_index > 0) {
            this.current_index -= 1
            this.current_song = Some(this.playlist[this.current_index])
            return true
        }
        return false
    }

    public func set_volume(volume: Int64): Bool {
        if (volume >= 0 && volume <= 100) {
            this.volume = volume
            return true
        }
        return false
    }

    public func shuffle(): Bool {
        if (this.playlist.isEmpty()) {
            return false
        }
        let rng = Random()
        for (i in this.playlist.size() - 1..0) {
            let j = rng.nextInt64(0, i + 1)
            let temp = this.playlist[i]
            this.playlist[i] = this.playlist[j]
            this.playlist[j] = temp
        }
        if (this.current_song != None) {
            let current = this.current_song.get()
            for (i in 0..this.playlist.size()) {
                if (this.playlist[i] == current) {
                    this.current_index = i
                    break
                }
            }
        }
        return true
    }
}

