import std.convert.*
import std.option.*

class NumberWordFormatter {

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case Some(s) => format_string(s)
            case None => ""
        }
    }

    public func format_string(x: String): String {
        let parts = x.split(".")
        let intPart = parts[0]
        let decPart = if (parts.size() > 1) { parts[1] } else { "" }

        let intWords = formatInteger(intPart)
        let decWords = if (decPart.length() > 0) { " POINT " + formatDecimal(decPart) } else { "" }

        intWords + decWords + " ONLY"
    }

    func formatInteger(s: String): String {
        if (s == "0") {
            return "ZERO"
        }
        var num = s
        var negative = false
        if (num[0] == '-') {
            negative = true
            num = num[1..]
        }
        let chunks = splitIntoThree(num)
        var result = ""
        for (i in 0..chunks.size()) {
            let chunk = chunks[i]
            if (chunk == "000") {
                continue
            }
            let words = trans_three(chunk)
            let suffix = parse_more((chunks.size() - i - 1).toInt64())
            let connector = if (result.length() > 0) { " " } else { "" }
            result = result + connector + words + (if (suffix != "") { " " + suffix } else { "" })
        }
        if (negative) {
            result = "MINUS " + result
        }
        result
    }

    func formatDecimal(s: String): String {
        var result = ""
        for (c in s) {
            let digit = Int32.parse(c.toString(), radix: 10)
            result = result + (if (result.length() > 0) { " " } else { "" }) + NUMBER[digit]
        }
        result
    }

    func splitIntoThree(s: String): Array<String> {
        var result = Array<String>([])
        var temp = s
        while (temp.length() > 0) {
            let len = temp.length()
            let start = if (len >= 3) { len - 3 } else { 0 }
            let chunk = temp[start..]
            result = [chunk, ...result]
            temp = temp[0..start]
        }
        result
    }

    public func trans_two(s: String): String {
        let n = Int64.parse(s, radix: 10)
        if (n < 10) {
            return NUMBER[n.toInt32()]
        } else if (n < 20) {
            return NUMBER_TEEN[(n - 10).toInt32()]
        } else {
            let ten = (n / 10).toInt32()
            let one = (n % 10).toInt32()
            let tenStr = NUMBER_TEN[ten - 1]
            let oneStr = if (one > 0) { " " + NUMBER[one] } else { "" }
            tenStr + oneStr
        }
    }

    public func trans_three(s: String): String {
        let n = Int64.parse(s, radix: 10)
        if (n < 100) {
            return trans_two(s)
        }
        let hundred = (n / 100).toInt32()
        let rest = (n % 100).toInt32()
        let hundredStr = NUMBER[hundred] + " HUNDRED"
        let restStr = if (rest > 0) { " AND " + trans_two(rest.toString()) } else { "" }
        hundredStr + restStr
    }

    public func parse_more(i: Int64): String {
        if (i < NUMBER_MORE.size()) {
            NUMBER_MORE[i.toInt32()]
        } else {
            ""
        }
    }
}

