import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        let buf = StringBuilder()
        let chars = string.toRuneArray()
        let len = chars.size()
        var i = 0
        while (i < len) {
            if (chars[i] == r'&' && i + 1 < len && chars[i + 1] == r'#') {
                var base = 10
                var start = i + 2
                if (start < len && chars[start] == r'x') {
                    base = 16
                    start += 1
                }
                var j = start
                while (j < len && chars[j] != r';') {
                    j += 1
                }
                if (j < len && chars[j] == r';') {
                    let numStr = String(chars[start..j])
                    match (base) {
                        10 => match (Int64.parse(numStr)) {
                            Ok(n) => {
                                buf.append(Rune(n))
                                i = j + 1
                                continue
                            }
                            Err(_) => {}
                        }
                        16 => match (UInt64.parse(numStr, radix: 16)) {
                            Ok(n) => {
                                buf.append(Rune(n))
                                i = j + 1
                                continue
                            }
                            Err(_) => {}
                        }
                        _ => {}
                    }
                }
            }
            buf.append(chars[i])
            i += 1
        }
        buf.toString()
    }

    public static func is_hex_char(char: Rune): Bool {
        char.isAsciiHex()
    }
}

