    if (page_number < 1 || page_number > total_pages) {
        return None
    }
    let page_data = get_page(page_number)
    let has_prev = page_number > 1
    let has_next = page_number < total_pages
    return Some(PageInfo(page_number, page_size, total_pages, total_items, has_prev, has_next, page_data))
}

