    let hits = ArrayList<Int64>()
    for (item in this.data) {
        if (item.toString().contains(keyword)) {
            hits.append(item)
        }
    }
    let total = hits.size
    let pages = (total + page_size - 1) / page_size
    return SearchInfo(keyword, total, pages, hits)
}

