import std.collection.ArrayList

class PushBoxGame {

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (i in 0..map.size()) {
                for (j in 0..map[i].size()) {
                    let c = map[i][j]
                    if (c == "O") {
                        this.player_row = i
                        this.player_col = j
                        this.map[i][j] = " "
                    } else if (c == "G") {
                        this.targets.append(ArrayList<Int64>([i, j]))
                        this.target_count++
                        this.map[i][j] = " "
                    } else if (c == "X") {
                        this.boxes.append(ArrayList<Int64>([i, j]))
                        this.map[i][j] = " "
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var covered: Int64 = 0
        for (box in this.boxes) {
            for (target in this.targets) {
                if (box == target) {
                    covered++
                    break
                }
            }
        }
        this.is_game_over = (covered == this.target_count)
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        let dr = direction == "w" ? -1 : direction == "s" ? 1 : 0
        let dc = direction == "a" ? -1 : direction == "d" ? 1 : 0
        let nr = this.player_row + dr
        let nc = this.player_col + dc

        if (this.map[nr][nc] == "#") {
            return false
        }

        var box_idx: Int64 = -1
        for (i in 0..this.boxes.size()) {
            if (this.boxes[i][0] == nr && this.boxes[i][1] == nc) {
                box_idx = i
                break
            }
        }

        if (box_idx >= 0) {
            let br = nr + dr
            let bc = nc + dc
            if (this.map[br][bc] == "#") {
                return false
            }
            for (b in this.boxes) {
                if (b[0] == br && b[1] == bc) {
                    return false
                }
            }
            this.boxes[box_idx][0] = br
            this.boxes[box_idx][1] = bc
        }

        this.player_row = nr
        this.player_col = nc
        return check_win()
    }

    public func print_map(): Unit {
        let disp = ArrayList<ArrayList<String>>()
        for (row in this.map) {
            disp.append(ArrayList<String>(row))
        }
        disp[this.player_row][this.player_col] = "O"
        for (box in this.boxes) {
            disp[box[0]][box[1]] = "X"
        }
        for (target in this.targets) {
            if (disp[target[0]][target[1]] == "X") {
                disp[target[0]][target[1]] = "*"
            } else {
                disp[target[0]][target[1]] = "G"
            }
        }
        for (row in disp) {
            println(String.join(row, " "))
        }
    }
}

