        if (!users.contains(username)) {
            return false
        }
        return users[username]
    }

    public func all_signed_in(): Bool {
        for ((_, v) in users) {
            if (!v) {
                return false
            }
        }
        return true
    }

    public func all_not_signed_in(): ArrayList<String> {
        let list = ArrayList<String>()
        for ((k, v) in users) {
            if (!v) {
                list.append(k)
            }
        }
        return list
    }
}

