import std.collection.ArrayList
import std.random.Random

class Snake {
    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>
    let rand: Random

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
        this.rand = Random()
    }

    public func move(direction: ArrayList<Int64>): Unit {
        let head = positions[0]
        let newX = head[0] + direction[0] * BLOCK_SIZE
        let newY = head[1] + direction[1] * BLOCK_SIZE
        let newHead = ArrayList<Int64>([newX, newY])
        positions.insert(0, newHead)
        if (newX == food_position[0] && newY == food_position[1]) {
            score += 100
            length += 1
            random_food_position()
        } else {
            positions.pop()
        }
        for (i in 1..positions.size) {
            if (positions[i][0] == newX && positions[i][1] == newY) {
                reset()
                return
            }
        }
    }

    public func random_food_position(): Unit {
        while (true) {
            let x = rand.nextInt64(SCREEN_WIDTH / BLOCK_SIZE) * BLOCK_SIZE
            let y = rand.nextInt64(SCREEN_HEIGHT / BLOCK_SIZE) * BLOCK_SIZE
            var onSnake = false
            for (p in positions) {
                if (p[0] == x && p[1] == y) {
                    onSnake = true
                    break
                }
            }
            if (!onSnake) {
                food_position[0] = x
                food_position[1] = y
                break
            }
        }
    }

    public func reset(): Unit {
        length = 1
        positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        score = 0
        random_food_position()
    }

    public func eat_food(): Unit {
        length += 1
        score += 100
        random_food_position()
    }
}

