import std.collection.ArrayList
import std.regex.Regex
import std.unicode.UnicodeStringExtension

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        let pattern = "(?<!(?:Mr|Mrs|Dr|Ms|St|Jr|Sr)|\\w\\.)[.!?](?=\\s|$)"
        let r = Regex(pattern)
        var list = ArrayList<String>()
        var prev = 0
        while (true) {
            let m = r.find(sentences_string[prev..], false)
            match (m) {
                case Some(mat) => {
                    let end = prev + mat.end
                    let part = sentences_string[prev..end].trimEnd()
                    if (part.size > 0) {
                        list.append(part)
                    }
                    prev = end
                }
                case None => {
                    let rest = sentences_string[prev..].trim()
                    if (rest.size > 0) {
                        list.append(rest)
                    }
                    break
                }
            }
        }
        return list
    }

    public func count_words(sentence: String): Int64 {
        let r = Regex("""[a-zA-Z]+""")
        var count = 0
        var rest = sentence
        while (true) {
            let m = r.find(rest, false)
            match (m) {
                case Some(mat) => {
                    count += 1
                    rest = rest[mat.end..]
                }
                case None => break
            }
        }
        return count
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = split_sentences(sentences_string)
        var maxWords = 0
        for (s in sentences) {
            let c = count_words(s)
            if (c > maxWords) {
                maxWords = c
            }
        }
        return maxWords
    }
}

