import std.collection.ArrayList
import std.collection.HashMap

class SQLGenerator {

    let table_name: String

    public init(table_name: String) {
        this.table_name = table_name
    }

    public func select(fields!: Option<ArrayList<String>> = None, condition!: Option<String> = None): String {
        let sb = StringBuilder()
        sb.append("SELECT ")
        match (fields) {
            case Some(f) =>
                if (f.size == 0) {
                    sb.append("*")
                } else {
                    sb.append(f.join(", "))
                }
            case None => sb.append("*")
        }
        sb.append(" FROM ")
        sb.append(table_name)
        match (condition) {
            case Some(c) =>
                sb.append(" WHERE ")
                sb.append(c)
            case None => ()
        }
        sb.append(";")
        sb.toString()
    }

    public func insert(data: HashMap<String, String>): String {
        let sb = StringBuilder()
        sb.append("INSERT INTO ")
        sb.append(table_name)
        sb.append(" (")
        let keys = data.keys()
        sb.append(keys.join(", "))
        sb.append(") VALUES (")
        let values = keys.map { k => "'${data[k]!}'" }
        sb.append(values.join(", "))
        sb.append(");")
        sb.toString()
    }

    public func update(data: HashMap<String, String>, condition: String): String {
        let sb = StringBuilder()
        sb.append("UPDATE ")
        sb.append(table_name)
        sb.append(" SET ")
        let pairs = data.keys().map { k => "${k} = '${data[k]!}'" }
        sb.append(pairs.join(", "))
        sb.append(" WHERE ")
        sb.append(condition)
        sb.append(";")
        sb.toString()
    }

    public func delete(condition: String): String {
        "DELETE FROM ${table_name} WHERE ${condition};"
    }

    public func select_female_under_age(age: Int64): String {
        "SELECT * FROM ${table_name} WHERE age < ${age} AND gender = 'female';"
    }

    public func select_by_age_range(min_age: Int64, max_age: Int64): String {
        "SELECT * FROM ${table_name} WHERE age BETWEEN ${min_age} AND ${max_age};"
    }
}

