class SQLQueryBuilder {
    public static func select(table: String, columns!: ArrayList<String> = ArrayList<String>(['*']), where_condition!: Option<HashMap<String, String>> = None): String {
        let colPart = columns.collectString(", ")
        var sql = "SELECT ${colPart} FROM ${table}"
        if (where_condition.isSome()) {
            let whereMap = where_condition.get()
            let whereClause = whereMap.keys().map<>(key => "${key}='${whereMap[key]}'").collectString(" AND ")
            sql = "${sql} WHERE ${whereClause}"
        }
        sql
    }

