import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.math.sqrt
import std.sort.sort

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let n = data.size()
        if (n == 0) {
            return 0.0
        }
        let sorted = ArrayList<Int64>()
        for (x in data) {
            sorted.append(x)
        }
        sort(sorted, (a: Int64, b: Int64) => { a < b })
        if (n % 2 == 1) {
            return Float64(sorted[n / 2])
        } else {
            return (Float64(sorted[n / 2 - 1]) + Float64(sorted[n / 2])) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq = HashMap<Int64, Int64>()
        for (x in data) {
            if (freq.get(x) is None) {
                freq[x] = 0
            }
            freq[x] = freq[x]! + 1
        }
        var maxFreq = 0
        for (k in freq.keys()) {
            if (freq[k]! > maxFreq) {
                maxFreq = freq[k]!
            }
        }
        let modes = ArrayList<Int64>()
        for (k in freq.keys()) {
            if (freq[k]! == maxFreq) {
                modes.append(k)
            }
        }
        sort(modes, (a: Int64, b: Int64) => { a < b })
        return modes
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        let n = data.size()
        if (n == 0) {
            return None
        }
        var sum: Float64 = 0.0
        for (x in data) {
            sum += Float64(x)
        }
        return Some(sum / Float64(n))
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let m = mean(data)
        if (m is None) {
            return None
        }
        let n = data.size()
        var sum = 0.0
        for (x in data) {
            let d = Float64(x) - m.get()
            sum += d * d
        }
        return Some(sqrt(sum / Float64(n)))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let n = data.size()
        if (n == 0) {
            return None
        }
        let m = mean(data).get()
        let sd = standard_deviation(data)
        if (sd is None) {
            return None
        }
        let sigma = sd.get()
        if (sigma == 0.0) {
            return None
        }
        let z = ArrayList<Float64>()
        for (x in data) {
            z.append((Float64(x) - m) / sigma)
        }
        return Some(z)
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        let nx = x.size()
        let ny = y.size()
        if (nx != ny || nx == 0) {
            return None
        }
        let mx = mean(x).get()
        let my = mean(y).get()
        var num = 0.0
        var denx = 0.0
        var deny = 0.0
        for (i in 0..nx) {
            let dx = Float64(x[i]) - mx
            let dy = Float64(y[i]) - my
            num += dx * dy
            denx += dx * dx
            deny += dy * dy
        }
        if (denx == 0.0 || deny == 0.0) {
            return None
        }
        return Some(num / sqrt(denx * deny))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let k = data.size()
        let mat = ArrayList<ArrayList<Float64>>()
        for (i in 0..k) {
            let row = ArrayList<Float64>()
            for (j in 0..k) {
                let c = correlation(data[i], data[j])
                if (c is None) {
                    row.append(0.0)
                } else {
                    row.append(c.get())
                }
