            map["value"] = s.price * Float64(s.quantity)
            list.append(map)
        }
        return (this.calculate_portfolio_value(), list)
    }

    public func get_stock_value(stock: Stock): Float64 {
        return stock.price * Float64(stock.quantity)
    }
}

