import std.collection.ArrayList

class TicTacToe {

    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(N!: Int64 = 3) {
        this.board = ArrayList<ArrayList<String>>()
        for (_ in 0..N) {
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(' ')
            }
            this.board.add(row)
        }
        this.current_player = 'X'
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if (row < 0 || row >= board.size() || col < 0 || col >= board[0].size()) {
            return false
        }
        if (board[row][col] != ' ') {
            return false
        }
        board[row][col] = current_player
        current_player = if (current_player == 'X') 'O' else 'X'
        true
    }

    public func check_winner(): Option<String> {
        let n = board.size()
        for (i in 0..n) {
            if (board[i][0] != ' ' &&
                board[i][0] == board[i][1] &&
                board[i][1] == board[i][2]) {
                return Some(board[i][0])
            }
        }
        for (j in 0..n) {
            if (board[0][j] != ' ' &&
                board[0][j] == board[1][j] &&
                board[1][j] == board[2][j]) {
                return Some(board[0][j])
            }
        }
        if (board[0][0] != ' ' &&
            board[0][0] == board[1][1] &&
            board[1][1] == board[2][2]) {
            return Some(board[0][0])
        }
        if (board[0][2] != ' ' &&
            board[0][2] == board[1][1] &&
            board[1][1] == board[2][0]) {
            return Some(board[0][2])
        }
        None
    }

    public func is_board_full(): Bool {
        for (row in board) {
            for (cell in row) {
                if (cell == ' ') {
                    return false
                }
            }
        }
        true
    }
}

