import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {
    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        let rad = x * PI / 180.0
        return taylor(x, 50)
    }

    public func factorial(a: Int64): Decimal {
        var res = Decimal(1)
        for (i in 1..=a) {
            res = res * Decimal(i)
        }
        return res
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        let rad = x * PI / 180.0
        var sum = 0.0
        for (k in 0..n) {
            let sig = (k % 2 == 0) ? 1.0 : -1.0
            let pow2k = 2 * k
            let num = sig * (rad ** Float64(pow2k))
            let den = Float64((factorial(pow2k)).toString())
            sum += num / den
        }
        return sum
    }

    public func sin(x: Float64): Float64 {
        let rad = x * PI / 180.0
        var sum = 0.0
        for (k in 0..50) {
            let sig = (k % 2 == 0) ? 1.0 : -1.0
            let pow2k1 = 2 * k + 1
            let num = sig * (rad ** Float64(pow2k1))
            let den = Float64((factorial(pow2k1)).toString())
            sum += num / den
        }
        return sum
    }

    public func tan(x: Float64): Option<Float64> {
        let c = cos(x)
        if (abs(c - 0.0) <= 0.000001) {
            return None
        }
        let s = sin(x)
        return Some(s / c)
    }
}

