    public init() {
        this.nums = ArrayList<Int64>()
    }

    public func _generate_cards(): Unit {
        let rand = Random()
        this.nums.clear()
        for (_ in 0..4) {
            this.nums.append(rand.nextInt64(1, 10))
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        this._generate_cards()
        return this.nums
    }

    public func answer(expression: String): Bool {
        if (!this.validate_expression(expression)) {
            return false
        }
        let result = this.evaluate_expression(expression)
        return result == 24
    }

    public func evaluate_expression(expression: String): Int64 {
        let parser = Parser(expression)
        return parser.parse()
    }

    private func validate_expression(expression: String): Bool {
        let allowedChars = "0123456789+-*/() "
        for (c in expression) {
            if (!allowedChars.contains(c.toString())) {
                return false
            }
        }

        var digitCounts = HashMap<Int64, Int64>()
        for (n in this.nums) {
            digitCounts[n] = digitCounts.getOrDefault(n, 0) + 1
        }

        var i = 0
        let runes = expression.toRunes()
        while (i < runes.size) {
            if (runes[i].isAsciiNumber()) {
                var start = i
                while (i < runes.size && runes[i].isAsciiNumber()) {
                    i += 1
                }
                let num = Int64.parse(expression[start..i])
                if (!digitCounts.contains(num) || digitCounts[num] == 0) {
                    return false
                }
                digitCounts[num] = digitCounts[num]! - 1
            } else {
                i += 1
            }
        }

        for (count in digitCounts.values) {
            if (count != 0) {
                return false
            }
        }
        return true
    }
}

