import std.collection.HashMap
import std.regex.*

class URLHandler {
    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let pattern = r"^([a-zA-Z][a-zA-Z0-9+.-]*):"
        let re = Regex(pattern)
        let m = re.match(this.url)
        if (m.has_value()) {
            return Some(m.value().group(1))
        }
        return None
    }

    public func get_host(): Option<String> {
        let pattern = r"://([^/?:#]+)"
        let re = Regex(pattern)
        let m = re.match(this.url)
        if (m.has_value()) {
            return Some(m.value().group(1))
        }
        return None
    }

    public func get_path(): Option<String> {
        let pattern = r"://[^/]*(/[^?#]*)"
        let re = Regex(pattern)
        let m = re.match(this.url)
        if (m.has_value()) {
            return Some(m.value().group(1))
        }
        return None
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let pattern = r"\?([^#]*)"
        let re = Regex(pattern)
        let m = re.match(this.url)
        if (!m.has_value()) {
            return None
        }
        let query = m.value().group(1)
        let map = HashMap<String, String>()
        for (part in query.split("&")) {
            let kv = part.split("=")
            if (kv.size == 2) {
                map[kv[0]] = kv[1]
            }
        }
        return Some(map)
    }

    public func get_fragment(): Option<String> {
        let pattern = r"#(.*)$"
        let re = Regex(pattern)
        let m = re.match(this.url)
        if (m.has_value()) {
            return Some(m.value().group(1))
        }
        return None
    }
}

