        if (!orders.containsKey(order_id)) {
            return false
        }
        orders[order_id]!.status = status
        return true
    }

    public func track_order(order_id: Int64): Option<String> {
        if (!orders.containsKey(order_id)) {
            return None
        }
        return Option<String>(orders[order_id]!.status)
    }
}

